  "inlineSchema": "// Prisma 7 + SQLite（本地 Demo / MVP 专用）\n// 数据库 URL 配置于 prisma.config.ts / .env\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n/// 案件持久化记录：索引字段 + 单一 caseState + 独立 reportDraft\nmodel CaseRecord {\n  id         String @id @default(cuid())\n  /// 稳定案件编号，如 INC-20260808-001；创建后永不变更\n  caseNumber String @unique\n  title      String\n\n  /// NEW | INVESTIGATING | PENDING_VERIFICATION | PENDING_BUSINESS_CONFIRMATION | RESPONDING | CLOSED\n  status String\n\n  suggestedRiskLevel String?\n  humanRiskLevel     String?\n  humanConclusion    String?\n\n  username          String?\n  sourceIp          String?\n  /// 全部涉及系统，以 | 拼接，便于 contains 搜索，例如：HR 系统|ERP 系统|CRM_PROD\n  systemsSearchText String?\n\n  pendingChecklistCount Int       @default(0)\n  hasReport             Boolean   @default(false)\n  /// 报告草稿最后写入时间；仅 saveReportDraft / 首次生成时更新，案件编辑不改动\n  reportUpdatedAt       DateTime?\n\n  /// 当前案件可恢复状态（PersistedCaseState JSON）\n  caseState   Json\n  /// 人工编辑后的报告草稿；null 表示尚未生成报告\n  reportDraft Json?\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  closedAt  DateTime?\n\n  /// 最后一次有意义的运营活动时间（成功写入 Audit 时更新；创建时等于 createdAt）\n  lastActivityAt DateTime @default(now())\n\n  /// 操作审计（append-only）；删除策略 Restrict，禁止静默级联删除\n  auditLogs CaseAuditLog[]\n\n  @@index([status])\n  @@index([updatedAt])\n  @@index([lastActivityAt])\n  @@index([username])\n  @@index([sourceIp])\n}\n\n/// 案件操作审计日志（与 Timeline 分离：记录研判人员/系统对案件的操作）\nmodel CaseAuditLog {\n  id     String     @id @default(cuid())\n  caseId String\n  case   CaseRecord @relation(fields: [caseId], references: [id], onDelete: Restrict)\n\n  /// AuditActionType（String 存储，Domain 侧 TS union）\n  actionType String\n\n  /// AuditActorType：SYSTEM | MANUAL | USER\n  actorType String\n  /// 登录用户 ID；MANUAL / SYSTEM 为 null；USER 时指向 User.id\n  actorId   String?\n  actor     User?   @relation(fields: [actorId], references: [id], onDelete: Restrict)\n  /// 展示名：系统 / 研判人员名 /「未填写研判人员」；MANUAL 非可信认证身份\n  actorName String?\n\n  /// 面向 UI 的一句话中文摘要（短）\n  summary String\n\n  /// 结构化变化（短字段，禁止整案快照）\n  changes  Json?\n  /// 可选元数据（如 handoff 原文、export 文件名）\n  metadata Json?\n\n  /// 可选：未来显式语义操作去重\n  operationId String? @unique\n\n  createdAt DateTime @default(now())\n\n  @@index([caseId, createdAt])\n  @@index([actionType])\n  @@index([actorId])\n}\n\n// ---------------------------------------------------------------------------\n// Better Auth identity / session（v1.3 Step 2）\n// Schema 对照自：npx auth@1.6.26 generate → scripts/.tmp/better-auth-schema.prisma\n// User.role 唯一物理 SoT：ADMIN | ANALYST | VIEWER（与 domain/auth 同名）\n// enabled：产品启用状态（server-owned）；banned* 为 Admin Plugin schema 字段，产品不调用\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id              String         @id\n  name            String\n  email           String\n  emailVerified   Boolean        @default(false)\n  image           String?\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n  username        String?\n  displayUsername String?\n  /// Security Triage UserRole 唯一 SoT：ADMIN | ANALYST | VIEWER\n  role            String?\n  /// Admin Plugin schema 字段；产品禁用态使用 enabled，不走 ban/unban\n  banned          Boolean?       @default(false)\n  banReason       String?\n  banExpires      DateTime?\n  /// 产品账号启用状态；DB NOT NULL + default true；input=false（server-owned）\n  enabled         Boolean        @default(true)\n  sessions        Session[]\n  accounts        Account[]\n  caseAuditLogs   CaseAuditLog[]\n\n  @@unique([email])\n  @@unique([username])\n  @@map(\"user\")\n}\n\nmodel Session {\n  id             String   @id\n  expiresAt      DateTime\n  token          String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  ipAddress      String?\n  userAgent      String?\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  impersonatedBy String?\n\n  @@unique([token])\n  @@index([userId])\n  @@map(\"session\")\n}\n\nmodel Account {\n  id                    String    @id\n  accountId             String\n  providerId            String\n  userId                String\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  /// Credential 密码哈希（Better Auth 管理）；禁止业务层 passwordHash\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  @@index([userId])\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([identifier])\n  @@map(\"verification\")\n}\n",
